class Solution {
    public int sumDistance(int[] nums,String s,int d){
        final long MOD=1000000007L;
        long[] positions=new long[nums.length];
        for(int i=0;i<nums.length;i++)positions[i]=(long)nums[i]+(s.charAt(i)=='R'?d:-d);
        Arrays.sort(positions);
        long prefix=0,answer=0;
        for(int i=0;i<positions.length;i++){
            answer=(answer+positions[i]*i-prefix)%MOD;
            prefix+=positions[i];
        }
        return (int)answer;
    }
}

code.kotlin:
class Solution {
    fun sumDistance(nums:IntArray,s:String,d:Int):Int{
        val mod=1000000007L;
        val positions=LongArray(nums.size){
            i->nums[i].toLong()+if(s[i]=='R')d.toLong() else -d.toLong()
        };
        positions.sort();
        var prefix=0L;
        var answer=0L;
        for(i in positions.indices){
            answer=(answer+positions[i]*i-prefix)%mod;
            prefix+=positions[i]
        };
        return answer.toInt()
    }
}

